const temperature = 25;

if (temperature > 30) {
  console.log("Жарко!");        // не выполнится
} else if (temperature > 20) {
  console.log("Тепло");         // выполнится — 25 > 20
} else if (temperature > 10) {
  console.log("Холодно");
} else {
  console.log("Очень холодно");
}

// Порядок else if ВАЖЕН: условия проверяются сверху вниз,
// и выполняется ТОЛЬКО первый подходящий блок.

const age = 20;
const status = age >= 18 ? "совершеннолетний" : "несовершеннолетний";
console.log(status);  // совершеннолетний

// То же самое через if/else (объёмнее):
let status2;
if (age >= 18) {
  status2 = "совершеннолетний";
} else {
  status2 = "несовершеннолетний";
}

// Тернарный можно вкладывать, но не делай этого:
// age >= 18 ? (age >= 65 ? "пенсионер" : "взрослый") : "ребёнок";
// Читаемость падает — используй if/else.

const day = "Monday";

switch (day) {
  case "Monday":
  case "Tuesday":
  case "Wednesday":
  case "Thursday":
  case "Friday":
    console.log("Рабочий день");
    break;  // без break протечёт в следующий case!
  case "Saturday":
  case "Sunday":
    console.log("Выходной");
    break;
  default:
    console.log("Неизвестный день");
}

// break — это 'стоп': если его нет, выполнение продолжится
// в следующий case. Смысл 'протекания': несколько case
// с одинаковым результатом можно объединить в одну ветку.

