function isEmpty(value) {
  // Проверяет: не null, не undefined, не пустая строка
  if (value != null && value !== "") {
    return false;  // есть значение
  }
  return true;  // пусто
}

console.log(isEmpty(""));    // true
console.log(isEmpty("0"));   // false — строка "0" не пустая
console.log(isEmpty(0));     // true — 0 не входит в проверку
console.log(isEmpty(null));  // true

